void MainViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &Climate)
    {
        //climate
        //When Climate clicked change screen to Climate
        //Go to Climate with screen transition towards East
        application().gotoClimateScreenCoverTransitionEast();
    }
    if (&src == &Lights)
    {
        //lights
        //When Lights clicked change screen to Lights
        //Go to Lights with screen transition towards East
        application().gotoLightsScreenCoverTransitionEast();
    }
    if (&src == &Music)
    {
        //music
        //When Music clicked change screen to Music
        //Go to Music with screen transition towards East
        application().gotoMusicScreenCoverTransitionEast();
    }
    if (&src == &Security)
    {
        //security
        //When Security clicked change screen to Security
        //Go to Security with screen transition towards East
        application().gotoSecurityScreenCoverTransitionEast();
    }
    if (&src == &back_1)
    {
        //back_1
        //When back_1 clicked change screen to Default
        //Go to Default with screen transition towards West
        application().gotoDefaultScreenSlideTransitionWest();
    }
    if (&src == &skip_main)
    {
        //onSkipMainClicked
        //When skip_main clicked call virtual function
        //Call onSkipMainClicked
        onSkipMainClicked();
    }
    if (&src == &back_main)
    {
        //Interaction1
        //When back_main clicked call virtual function
        //Call onBackMainClicked
        onBackMainClicked();
    }
    if (&src == &play_pause_main)
    {
        //onPlayPauseMainClicked
        //When play_pause_main clicked call virtual function
        //Call onPlayPauseMainClicked
        onPlayPauseMainClicked();
    }
    if (&src == &bedtime)
    {
        //onBedtimeClicked
        //When bedtime clicked call virtual function
        //Call onBedtimeClicked
        onBedtimeClicked();
    }
    if (&src == &wakeup)
    {
        //onWakeupClicked
        //When wakeup clicked call virtual function
        //Call onWakeupClicked
        onWakeupClicked();
    }
}
